"""Hand-curated entity facts per delivery case, read from the case text (events 001-005 and the index).

These fill the operational objects of Andrey Zharkov's system model (user/andrey/drafts/delivery-system-model.md):
Order, Shipment, Parcel. Values are the case's own words; 'N/A' means the case never states it.
`milestone_at_escalation` and `milestone_final` use the draft's shipment state machine; where the draft has no
state (pickup point, customs, misdelivery, returns) the nearest state is used and `model_gap` names the gap.
"""

NA = 'N/A'
PLOVER = 'Plover Arc Logistics'
TG = 'Tallowmere Goods'


def ship(sid, kind='delivery', carrier=NA, m_esc=NA, m_final=NA, exc=NA, dest=NA, promised=NA, gap=NA,
         shipper=NA, consignee=NA, note=NA):
    return dict(shipment_id=sid, kind=kind, carrier_id=carrier, milestone_at_escalation=m_esc, milestone_final=m_final,
                exception=exc, destination=dest, promised_at=promised, model_gap=gap, shipper=shipper, consignee=consignee, note=note)


def parcel(pid, sid, status=NA, note=NA):
    return dict(parcel_id=pid, shipment_id=sid, barcode=NA, parcel_status=status, note=note)


